INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-top-security-policy-hits', 'Default dashboard', 'qgw', 'SELECT rule_id, action, SUM(hit_count) AS hits FROM security_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id, action ORDER BY hits DESC LIMIT ${limit}', 'Security Policy Hits-Top Hits. List of security rules with the highest hit count.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-security-policy-hits-by-action', 'Default dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, (CASE WHEN action = 1 THEN ''Monitor'' WHEN action = 16 THEN ''Deny'' WHEN action = 96 THEN ''Allow'' WHEN action = 128 THEN ''Shunt'' ELSE concat(action) END) AS action, AVG(sum_hit_count)/1 AS avg_hit_count_per_sec, AVG(sum_bytes)*8/1 AS avg_bits_per_sec, AVG(sum_packets)/1 AS avg_pkts_per_sec, SUM(sum_hit_count) AS total_hit_count, SUM(sum_bytes) AS total_bytes, SUM(sum_packets) AS total_packets FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') AS stat_time, action, sum(hit_count) AS sum_hit_count, sum(in_bytes + out_bytes) AS sum_bytes, sum(in_pkts + out_pkts) AS sum_packets FROM security_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S''), action ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')), action ORDER BY stat_time ASC LIMIT ${limit}', 'Security Policy Hits-Policy Hits by Action. The security policy rule hit count, bytes, and packets of action over the selected time frame.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-top-proxy-policy-hits', 'Default dashboard', 'qgw', 'SELECT rule_id, action AS action, sub_action, SUM( hit_count ) AS hits FROM proxy_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id, action, sub_action ORDER BY hits DESC LIMIT ${limit}', 'Proxy Policy Hits-Top Hits. List of proxy rules with the highest hit count.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-proxy-manipulation-policy-hits-by-action', 'Default dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, action AS action, AVG( sum_hit_count )/ 1 AS avg_hit_count_per_sec, SUM( sum_hit_count ) AS total_hit_count FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') AS stat_time, sub_action AS action, sum( hit_count ) AS sum_hit_count FROM proxy_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND action = 48 AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S''), sub_action ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')), action ORDER BY stat_time ASC LIMIT ${limit}', 'Proxy Policy Hits-Manipulation Policy Hits by Action. The proxy manipulation policy hit the count of action over the selected time frame.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-proxy-ssl-intercept-pinning-summary', 'Default dashboard', 'qgw', 'SELECT ( CASE WHEN pinning_status = 0 THEN ''not_pinning_num'' WHEN pinning_status = 1 THEN ''pinning_num'' WHEN pinning_status = 2 THEN ''maybe_pinning_num'' ELSE concat( pinning_status ) END ) AS type, SUM( hit_count ) AS hits FROM proxy_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND action = 2 AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY pinning_status ORDER BY pinning_status', 'Proxy Policy Hits-Pinning summary.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-proxy-ssl-intercept-pinning-trend', 'Default dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( CASE WHEN pinning_status = 0 THEN sum_hit_count ELSE 0 END )/ 1 AS avg_not_pinning_hit_count_per_sec, AVG( CASE WHEN pinning_status = 1 THEN sum_hit_count ELSE 0 END )/ 1 AS avg_pinning_hit_count_per_sec, AVG( CASE WHEN pinning_status = 2 THEN sum_hit_count ELSE 0 END )/ 1 AS avg_maybe_pinning_hit_count_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') AS stat_time, pinning_status, SUM( hit_count ) AS sum_hit_count, SUM( in_bytes + out_bytes ) AS sum_bytes FROM proxy_rule_hits WHERE __time >= ''${start}'' AND __time <''${end}'' AND vsys_id IN ( ${vsys_id} ) AND action = 2 AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S''), pinning_status ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}', 'Proxy Policy Hits-Pinning trend. Monitor SSL Pinning over the selected time frame.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-current-network-throughput', 'Default dashboard', 'qgw', 'SELECT SUM( sum_in_bytes )* 8 / 15 AS avg_in_bits_per_sec, SUM( sum_out_bytes )* 8 / 15 AS avg_out_bits_per_sec, SUM( sum_in_bytes + sum_out_bytes )* 8 / 15 AS avg_bits_per_sec, SUM( sum_in_bytes )/ 15 AS avg_in_bytes_per_sec, SUM( sum_out_bytes )/ 15 AS avg_out_bytes_per_sec, SUM( sum_in_bytes + sum_out_bytes )/ 15 AS avg_bytes_per_sec, SUM( sum_in_pkts )/ 15 AS avg_in_pkts_per_sec, SUM( sum_out_pkts )/ 15 AS avg_out_pkts_per_sec, SUM( sum_in_pkts + sum_out_pkts )/ 15 AS avg_pkts_per_sec, SUM( sum_sessions )/ 15 AS avg_sessions_per_sec, SUM( max_active_sessions ) AS active_sessions FROM ( SELECT device_id, vsys_id, SUM( in_bytes ) AS sum_in_bytes, SUM( out_bytes ) AS sum_out_bytes, SUM( in_pkts ) AS sum_in_pkts, SUM( out_pkts ) AS sum_out_pkts, SUM( sessions ) AS sum_sessions, max( active_sessions ) AS max_active_sessions FROM traffic_general_stat WHERE __time >= FROM_UNIXTIME( UNIX_TIMESTAMP( now())- 30 ) AND __time < FROM_UNIXTIME( UNIX_TIMESTAMP( now())- 15 ) AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY device_id, vsys_id )', 'System Overview-Traffic-Now. To calculate the current throughput, the metrics for each appliance are averaged over a 15-second interval. Additionally, the data ingestion latency is also set at 15 seconds.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-network-throughput-bit-per-second', 'Default dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( stat_time, ''${alignment_period}'', ''zero'' )) AS stat_time, AVG( sum_in_bytes )* 8 / 5 AS avg_in_bits_per_sec, AVG( sum_out_bytes )* 8 / 5 AS avg_out_bits_per_sec, AVG( sum_bytes )* 8 / 5 AS avg_bits_per_sec, MAX( sum_in_bytes )* 8 / 5 AS max_in_bits_per_sec, MAX( sum_out_bytes )* 8 / 5 AS max_out_bits_per_sec, MAX( sum_bytes )* 8 / 5 AS max_bits_per_sec, MIN( sum_in_bytes )* 8 / 5 AS min_in_bits_per_sec, MIN( sum_out_bytes )* 8 / 5 AS min_out_bits_per_sec, MIN( sum_bytes )* 8 / 5 AS min_bits_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, SUM( in_bytes ) AS sum_in_bytes, SUM( out_bytes ) AS sum_out_bytes, SUM( in_bytes + out_bytes ) AS sum_bytes FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( stat_time, ''${alignment_period}'', ''zero'' )) ORDER BY stat_time ASC LIMIT ${limit}', 'System Overview-Traffic-AVG, MAX, MIN.\r\n\r\nTo calculate network throughput, supports metric types \"bytes\" and \"packets,\" and offers aggregation methods including \"average\" (avg), \"maximum\" (max), and \"minimum\" (min). Based on MAX and MIN values can reveal abnormal traffic patterns, such as peak and valley outliers.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-network-throughput-byte-per-second', 'Default dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( sum_in_bytes )/ 5 AS avg_in_bytes_per_sec, AVG( sum_out_bytes )/ 5 AS avg_out_bytes_per_sec, AVG( sum_bytes )/ 5 AS avg_bytes_per_sec, MAX( sum_in_bytes )/ 5 AS max_in_bytes_per_sec, MAX( sum_out_bytes )/ 5 AS max_out_bytes_per_sec, MAX( sum_bytes )/ 5 AS max_bytes_per_sec, MIN( sum_in_bytes )/ 5 AS min_in_bytes_per_sec, MIN( sum_out_bytes )/ 5 AS min_out_bytes_per_sec, MIN( sum_bytes )/ 5 AS min_bytes_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, SUM( in_bytes ) AS sum_in_bytes, SUM( out_bytes ) AS sum_out_bytes, SUM( in_bytes + out_bytes ) AS sum_bytes FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}', 'System Overview-Traffic-AVG, MAX, MIN.\r\n\r\nTo calculate network throughput, supports metric types \"bytes\" and \"packets,\" and offers aggregation methods including \"average\" (avg), \"maximum\" (max), and \"minimum\" (min). Based on MAX and MIN values can reveal abnormal traffic patterns, such as peak and valley outliers.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-network-throughput-packet-per-second', 'Default dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( sum_in_pkts )/ 5 AS avg_in_pkts_per_sec, AVG( sum_out_pkts )/ 5 AS avg_out_pkts_per_sec, AVG( sum_pkts )/ 5 AS avg_pkts_per_sec, MAX( sum_in_pkts )/ 5 AS max_in_pkts_per_sec, MAX( sum_out_pkts )/ 5 AS max_out_pkts_per_sec, MAX( sum_pkts )/ 5 AS max_pkts_per_sec, MIN( sum_in_pkts )/ 5 AS min_in_pkts_per_sec, MIN( sum_out_pkts )/ 5 AS min_out_pkts_per_sec, MIN( sum_pkts )/ 5 AS min_pkts_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, SUM( in_pkts ) AS sum_in_pkts, SUM( out_pkts ) AS sum_out_pkts, SUM( in_pkts + out_pkts ) AS sum_pkts FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}', 'System Overview-Traffic-AVG, MAX, MIN.\r\n\r\nTo calculate network throughput, supports metric types \"bytes\" and \"packets,\" and offers aggregation methods including \"average\" (avg), \"maximum\" (max), and \"minimum\" (min). Based on MAX and MIN values can reveal abnormal traffic patterns, such as peak and valley outliers.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-new-sessions-per-second', 'Default dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( sum_sessions )/ 5 AS avg_sessions_per_sec, MAX( sum_sessions )/ 5 AS max_sessions_per_sec, MIN( sum_sessions )/ 5 AS min_sessions_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, SUM( sessions ) AS sum_sessions FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}', 'System Overview-New-AVG, MAX, MIN.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-active-sessions', 'Default dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( sum_active_sessions ) AS avg_active_sessions, MAX( sum_active_sessions ) AS max_active_sessions, MIN( sum_active_sessions ) AS min_active_sessions FROM ( SELECT stat_time, SUM( max_active_sessions ) sum_active_sessions FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, device_id, vsys_id, MAX( active_sessions ) AS max_active_sessions FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S''), device_id, vsys_id ) GROUP BY stat_time ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}', 'System Overview-New-AVG, MAX, MIN.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-top-client-ips', 'Default dashboard', 'qgw', 'SELECT client_ip AS client_ip, SUM( sessions ) AS sessions, SUM( in_bytes ) AS in_bytes, SUM( out_bytes ) AS out_bytes, SUM( in_bytes + out_bytes ) AS bytes, SUM( in_pkts ) AS in_packets, SUM( out_pkts ) AS out_packets, SUM( in_pkts + out_pkts ) AS packets FROM top_client_ips WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND metric = ''${metric}'' AND ( ${filter} ) GROUP BY client_ip ORDER BY ${metric} DESC LIMIT ${limit}', 'Endpoints-Top Client IPs. Aggregate traffic sessions, bytes, and packets based on the client''s IP address. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-top-server-ips', 'Default dashboard', 'qgw', 'SELECT server_ip AS server_ip, SUM( sessions ) AS sessions, SUM( in_bytes ) AS in_bytes, SUM( out_bytes ) AS out_bytes, SUM( in_bytes + out_bytes ) AS bytes, SUM( in_pkts ) AS in_packets, SUM( out_pkts ) AS out_packets, SUM( in_pkts + out_pkts ) AS packets FROM top_server_ips WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND metric = ''${metric}'' AND ( ${filter} ) GROUP BY server_ip ORDER BY ${metric} DESC LIMIT ${limit}', 'Endpoints-Top Server IPs. Aggregate traffic sessions, bytes, and packets based on the server IP address. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
