INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-top-server-domains', 'Default dashboard', 'qgw', 'SELECT domain, SUM( sessions ) AS sessions, SUM( in_bytes ) AS in_bytes, SUM( out_bytes ) AS out_bytes, SUM( in_bytes + out_bytes ) AS bytes, SUM( in_pkts ) AS in_packets, SUM( out_pkts ) AS out_packets, SUM( in_pkts + out_pkts ) AS packets FROM top_server_domains WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND metric = ''${metric}'' AND ( ${filter} ) GROUP BY domain ORDER BY ${metric} DESC LIMIT ${limit}', 'Endpoints-Top Server Domains. Aggregate traffic sessions, bytes, and packets based on the server domains. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-top-server-fqdns', 'Default dashboard', 'qgw', 'SELECT fqdn, SUM( sessions ) AS sessions, SUM( in_bytes ) AS in_bytes, SUM( out_bytes ) AS out_bytes, SUM( in_bytes + out_bytes ) AS bytes, SUM( in_pkts ) AS in_packets, SUM( out_pkts ) AS out_packets, SUM( in_pkts + out_pkts ) AS packets FROM top_server_fqdns WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND metric = ''${metric}'' AND ( ${filter} ) GROUP BY fqdn ORDER BY ${metric} DESC LIMIT ${limit}', 'Endpoints-Top Server FQDNs. Aggregate traffic sessions, bytes, and packets based on the server FQDNs. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-top-subscribers', 'Default dashboard', 'qgw', 'SELECT subscriber_id, SUM( sessions ) AS sessions, SUM( in_bytes ) AS in_bytes, SUM( out_bytes ) AS out_bytes, SUM( in_bytes + out_bytes ) AS bytes, SUM( in_pkts ) AS in_packets, SUM( out_pkts ) AS out_packets, SUM( in_pkts + out_pkts ) AS packets FROM top_subscribers WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND metric = ''${metric}'' AND ( ${filter} ) GROUP BY subscriber_id ORDER BY ${metric} DESC LIMIT ${limit}', 'Endpoints-Top Subscribers. Aggregate traffic sessions, bytes, and packets based on the subscribers. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-top-applications', 'Default dashboard', 'qgw', 'SELECT app_name, SUM( sessions ) AS sessions, SUM( in_bytes ) AS in_bytes, SUM( out_bytes ) AS out_bytes, SUM( in_bytes + out_bytes ) AS bytes, SUM( in_pkts ) AS in_packets, SUM( out_pkts ) AS out_packets, SUM( in_pkts + out_pkts ) AS packets FROM application_protocol_stat WHERE __time >= ''${start}'' AND __time <''${end}'' AND vsys_id IN ( ${vsys_id} ) AND app_name IS NOT NULL AND ( ${filter} ) GROUP BY app_name ORDER BY ${metric} DESC LIMIT ${limit}', 'Endpoints-Top Applications. Aggregate traffic sessions, bytes, and packets based on the applications. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-client-ips', 'user-defined dashboard', 'qgw', 'SELECT client_ip AS client_ip, SUM( sessions ) AS sessions, SUM( out_bytes ) AS out_bytes, SUM( in_bytes ) AS in_bytes, SUM( out_bytes + in_bytes ) AS bytes, SUM( out_pkts ) AS out_packets, SUM( in_pkts ) AS in_packets, SUM( out_pkts + in_pkts ) AS packets FROM top_client_ips WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND metric = ''${metric}'' AND ( ${filter} ) GROUP BY client_ip ORDER BY ${metric} DESC LIMIT ${limit}', 'Aggregate traffic sessions, bytes, and packets based on the client''s IP address. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-server-ips', 'user-defined dashboard', 'qgw', 'SELECT server_ip AS server_ip, SUM( sessions ) AS sessions, SUM( out_bytes ) AS out_bytes, SUM( in_bytes ) AS in_bytes, SUM( out_bytes + in_bytes ) AS bytes, SUM( out_pkts ) AS out_packets, SUM( in_pkts ) AS in_packets, SUM( out_pkts + in_pkts) AS packets FROM top_server_ips WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) AND metric = ''${metric}'' GROUP BY server_ip ORDER BY ${metric} DESC LIMIT ${limit}', 'Aggregate traffic sessions, bytes, and packets based on the server IP address. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-internal-ips', 'user-defined dashboard', 'qgw', 'SELECT internal_ip AS internal_ip, SUM( sessions ) AS sessions, SUM( out_bytes ) AS out_bytes, SUM( in_bytes ) AS in_bytes, SUM( out_bytes + in_bytes ) AS bytes, SUM( out_pkts ) AS out_packets, SUM( in_pkts ) AS in_packets, SUM( out_pkts + in_pkts ) AS packets FROM top_internal_ips WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) AND metric = ''${metric}'' GROUP BY internal_ip ORDER BY ${metric} DESC LIMIT ${limit}', 'Aggregate traffic sessions, bytes, and packets based on the internal IP address. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-external-ips', 'user-defined dashboard', 'qgw', 'SELECT external_ip AS external_ip, SUM( sessions ) AS sessions, SUM( out_bytes ) AS out_bytes, SUM( in_bytes ) AS in_bytes, SUM( out_bytes + in_bytes ) AS bytes, SUM( out_pkts ) AS out_packets, SUM( in_pkts ) AS in_packets, SUM( out_pkts + in_pkts ) AS packets FROM top_external_ips WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) AND metric = ''${metric}'' GROUP BY external_ip ORDER BY ${metric} DESC LIMIT ${limit}', 'Aggregate traffic sessions, bytes, and packets based on the external IP address. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-subscribers', 'user-defined dashboard', 'qgw', 'SELECT subscriber_id, SUM( sessions ) AS sessions, SUM( out_bytes ) AS out_bytes, SUM( in_bytes ) AS in_bytes, SUM( out_bytes + in_bytes ) AS bytes, SUM( out_pkts ) AS out_packets, SUM( in_pkts ) AS in_packets, SUM( out_pkts+ in_pkts ) AS packets FROM top_subscribers WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) AND metric = ''${metric}'' GROUP BY subscriber_id ORDER BY ${metric} DESC LIMIT ${limit}', 'Aggregate traffic sessions, bytes, and packets based on the subscribers. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-server-domains', 'user-defined dashboard', 'qgw', 'SELECT domain, SUM( sessions ) AS sessions, SUM( out_bytes ) AS out_bytes, SUM( in_bytes ) AS in_bytes, SUM( out_bytes + in_bytes ) AS bytes, SUM( out_pkts) AS out_packets, SUM( in_pkts ) AS in_packets, SUM( out_pkts + in_pkts ) AS packets FROM top_server_domains WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) AND metric = ''${metric}'' GROUP BY domain ORDER BY ${metric} DESC LIMIT ${limit}', 'Aggregate traffic sessions, bytes, and packets based on the server domains. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-server-fqdns', 'user-defined dashboard', 'qgw', 'SELECT fqdn, SUM( sessions ) AS sessions, SUM( out_bytes ) AS out_bytes, SUM( in_bytes ) AS in_bytes, SUM( out_bytes + in_bytes ) AS bytes, SUM( out_pkts ) AS out_packets, SUM( in_pkts ) AS in_packets, SUM( out_pkts + in_pkts ) AS packets FROM top_server_fqdns WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) AND metric = ''${metric}'' GROUP BY fqdn ORDER BY ${metric} DESC LIMIT ${limit}', 'Aggregate traffic sessions, bytes, and packets based on the server FQDNs. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-applications', 'user-defined dashboard', 'qgw', 'SELECT app_name, SUM( sessions ) AS sessions, SUM( in_bytes ) AS in_bytes, SUM( out_bytes ) AS out_bytes, SUM( in_bytes + out_bytes ) AS bytes, SUM( in_pkts ) AS in_packets, SUM( out_pkts ) AS out_packets, SUM( in_pkts + out_pkts ) AS packets FROM application_protocol_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND app_name IS NOT NULL AND ( ${filter} ) GROUP BY app_name ORDER BY ${metric} DESC LIMIT ${limit}', 'Aggregate traffic sessions, bytes, and packets based on the applications. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-network-throughput', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( sum_in_bytes )* 8 / 5 AS avg_in_bits_per_sec, AVG( sum_out_bytes )* 8 / 5 AS avg_out_bits_per_sec, AVG( sum_bytes )* 8 / 5 AS avg_bits_per_sec, AVG( sum_in_bytes )/ 5 AS avg_in_bytes_per_sec, AVG( sum_out_bytes )/ 5 AS avg_out_bytes_per_sec, AVG( sum_bytes )/ 5 AS avg_bytes_per_sec, AVG( sum_in_pkts )/ 5 AS avg_in_pkts_per_sec, AVG( sum_out_pkts )/ 5 AS avg_out_pkts_per_sec, AVG( sum_pkts )/ 5 AS avg_pkts_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, SUM( in_bytes ) AS sum_in_bytes, SUM( out_bytes ) AS sum_out_bytes, SUM( in_bytes + out_bytes ) AS sum_bytes, SUM( in_pkts ) AS sum_in_pkts, SUM( out_pkts ) AS sum_out_pkts, SUM( in_pkts + out_pkts ) AS sum_pkts FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}', 'The calculation of average network throughput is capable of supporting two types of metrics, namely \"bytes\" and \"packets\".', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-new-sessions-per-second', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, avg( sum_sessions )/ 5 AS avg_sessions_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, sum( sessions ) AS sum_sessions FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-active-sessions', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( sum_active_sessions ) AS avg_active_sessions FROM ( SELECT stat_time, SUM( max_active_sessions ) sum_active_sessions FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, device_id, vsys_id, MAX( active_sessions ) AS max_active_sessions FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S''), device_id, vsys_id ) GROUP BY stat_time ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-asymmetric-flows', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( sum_bytes )* 8 / 5 AS avg_bits_per_sec, round( CASE WHEN sum( sum_closed_sessions ) = 0 THEN 0 ELSE SUM( sum_asymmetric_flows ) * 1.0 / SUM( sum_closed_sessions ) END, 4 ) * 100 AS percent_asymmetric_flows FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, SUM( in_bytes ) AS sum_in_bytes, SUM( out_bytes ) AS sum_out_bytes, SUM( in_bytes + out_bytes ) AS sum_bytes, SUM( closed_sessions ) AS sum_closed_sessions, SUM( asymmetric_c2s_flows + asymmetric_s2c_flows ) AS sum_asymmetric_flows FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-traffic-shapping-policy-dropped-packets', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''${alignment_period}'', ''zero'')) AS stat_time, rule_id, SUM( in_drop_pkts + out_drop_pkts ) AS sum_dropped_packets FROM traffic_shaping_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''${alignment_period}'', ''zero'')), rule_id ORDER BY stat_time ASC LIMIT ${limit}', 'The dropped packets for different traffic shaping rules over a selected time frame.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-traffic-shaping-policy-throughput', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, rule_id, AVG( sum_bytes )* 8 / 1 AS avg_bits_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') AS stat_time, rule_id, SUM( in_bytes + out_bytes ) AS sum_bytes FROM traffic_shaping_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S''), rule_id ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')), rule_id ORDER BY stat_time ASC LIMIT ${limit}', 'The throughput of traffic shaping rule over a selected time frame', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-service-chaining-policy-throughput', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, rule_id, AVG( sum_bytes )* 8 / 1 AS avg_bits_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') AS stat_time, rule_id, SUM( sent_bytes + recv_bytes ) AS sum_bytes FROM service_chaining_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S''), rule_id ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')), rule_id ORDER BY stat_time ASC LIMIT ${limit}', 'The throughput of the service chaining rule over a selected time frame.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-application-usage', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, app_name, AVG( sum_in_bytes )* 8 / 15 AS avg_in_bits_per_sec, AVG( sum_out_bytes )* 8 / 15 AS avg_out_bits_per_sec, AVG( sum_bytes )* 8 / 15 AS avg_bits_per_sec, AVG( sum_in_pkts )/ 15 AS avg_in_pkts_per_sec, AVG( sum_out_pkts )/ 15 AS avg_out_pkts_per_sec, AVG( sum_pkts )/ 15 AS avg_pkts_per_sec, AVG( sum_sessions )/ 15 AS avg_sessions_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT15S'') AS stat_time, app_name, SUM( sessions ) AS sum_sessions, SUM( in_bytes ) AS sum_in_bytes, SUM( out_bytes ) AS sum_out_bytes, SUM( in_bytes + out_bytes ) AS sum_bytes, SUM( in_pkts ) AS sum_in_pkts, SUM( out_pkts ) AS sum_out_pkts, SUM( in_pkts + out_pkts ) AS sum_pkts FROM application_protocol_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) AND app_name IS NOT NULL GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT15S''), app_name ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')), app_name ORDER BY stat_time ASC LIMIT ${limit}', 'Real-time traffic sessions, bytes, and packets of favorite applications over a selected time frame.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-security-policy-hits-metric', 'user-defined dashboard', 'qgw', 'SELECT rule_id AS rule_id, SUM( hit_count ) AS hit_count, SUM( in_bytes + out_bytes ) AS bytes FROM security_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id ORDER BY ${metric} DESC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-proxy-policy-hits-by-manipulation-action', 'user-defined dashboard', 'qgw', 'SELECT rule_id AS rule_id, action AS action, sub_action AS sub_action, SUM( hit_count ) AS hit_count, SUM( in_bytes + out_bytes ) AS bytes FROM proxy_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id, action, sub_action ORDER BY ${metric} DESC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-security-policy-usage', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, rule_id, avg( sum_hit_count )/ 1 AS avg_hit_count_per_sec, avg( sum_bytes )* 8 / 1 AS avg_bits_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') AS stat_time, rule_id, sum( hit_count ) AS sum_hit_count, sum( in_bytes + out_bytes ) AS sum_bytes FROM security_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S''), rule_id ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')), rule_id ORDER BY stat_time ASC LIMIT ${limit}', 'The hit count and bytes of the favorite security policy rule over the selected time frame.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-proxy-policy-usage', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, rule_id, avg( sum_hit_count )/ 1 AS avg_hit_count_per_sec, avg( sum_bytes )* 8 / 1 AS avg_bits_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') AS stat_time, rule_id, sum( hit_count ) AS sum_hit_count, sum( in_bytes + out_bytes ) AS sum_bytes FROM proxy_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S''), rule_id ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')), rule_id ORDER BY stat_time ASC LIMIT ${limit}', 'The hit count and bytes of the favorite proxy policy rule over the selected time frame.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-proxy-ssl-intercept-pinning-trend', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( CASE WHEN pinning_status = 0 THEN sum_hit_count ELSE 0 END )/ 1 AS avg_not_pinning_hit_count_per_sec, AVG( CASE WHEN pinning_status = 1 THEN sum_hit_count ELSE 0 END )/ 1 AS avg_pinning_hit_count_per_sec, AVG( CASE WHEN pinning_status = 2 THEN sum_hit_count ELSE 0 END )/ 1 AS avg_maybe_pinning_hit_count_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') AS stat_time, pinning_status, SUM( hit_count ) AS sum_hit_count, SUM( in_bytes + out_bytes ) AS sum_bytes FROM proxy_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND action = 2 AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S''), pinning_status ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}', 'Monitor SSL Pinning over the selected time frame.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-security-policy-hits-by-action', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, (CASE WHEN action = 1 THEN ''Monitor'' WHEN action = 2 THEN ''Intercept'' WHEN action = 16 THEN ''Deny'' WHEN action = 48 THEN ''Manipulation'' WHEN action = 96 THEN ''Allow'' WHEN action = 128 THEN ''Shunt'' ELSE concat( action ) END ) AS action, AVG( sum_hit_count )/ 1 AS avg_hit_count_per_sec, AVG( sum_bytes )* 8 / 1 AS avg_bits_per_sec, AVG( sum_packets )/ 1 AS avg_pkts_per_sec, SUM( sum_hit_count ) AS total_hit_count, SUM( sum_bytes ) AS total_bytes, SUM( sum_packets ) AS total_packets FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') AS stat_time, action, SUM( hit_count ) AS sum_hit_count, SUM( in_bytes + out_bytes ) AS sum_bytes, SUM( in_pkts + out_pkts ) AS sum_packets FROM security_rule_hits WHERE __time >= ''${start}'' AND __time <  ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S''), action ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')), action ORDER BY stat_time ASC LIMIT ${limit}', 'The security policy rule hit count, bytes, and packets of action over the selected time frame.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-proxy-policy-hits-by-action', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, (CASE WHEN action = 2 THEN ''Intercept'' WHEN action = 3 THEN ''No Intercept'' WHEN action = 48 THEN ''Manipulation'' ELSE concat( action ) END ) AS action, AVG( sum_hit_count )/ 1 AS avg_hit_count_per_sec, SUM( sum_hit_count ) AS total_hit_count FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') AS stat_time, action AS action, SUM( hit_count ) AS sum_hit_count FROM proxy_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S''), action ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')), action ORDER BY stat_time ASC LIMIT ${limit}', 'The proxy Intercept policy hit the count of action over the selected time frame.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-proxy-manipulation-policy-hits-by-action', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, action AS action, AVG( sum_hit_count )/ 1 AS avg_hit_count_per_sec, SUM( sum_hit_count ) AS total_hit_count FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') AS stat_time, sub_action AS action, SUM( hit_count ) AS sum_hit_count FROM proxy_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND action = 48 AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S''), sub_action ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')), action ORDER BY stat_time ASC LIMIT ${limit}', 'The proxy manipulation policy hit the count of action over the selected time frame.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-security-policy-hits', 'user-defined dashboard', 'qgw', 'SELECT rule_id, action, SUM( hit_count) AS hit_count, SUM( in_bytes + out_bytes ) AS bytes FROM security_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id, action ORDER BY hit_count DESC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-proxy-policy-hits', 'user-defined dashboard', 'qgw', 'SELECT rule_id, SUM( hit_count ) AS hit_count, SUM( in_bytes + out_bytes ) AS bytes FROM proxy_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id ORDER BY hit_count DESC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('security-rule-hits-summary', 'security rule hits', 'qgw', 'SELECT rule_id, SUM(hit_count) as hits, SUM(in_bytes + out_bytes) as bytes FROM security_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND rule_id IN ( ${rule_id} ) AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id', 'The hit count of specific rules.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('security-rule-hits-trend', 'security rule hits', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) AS stat_time, SUM(hit_count) AS hits FROM security_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND rule_id IN (${rule_id}) AND vsys_id IN (${vsys_id}) AND ( ${filter} ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) LIMIT ${limit}', 'The trend of hit count by specific rule over a period of time.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('security-rule-hits-first-and-last-hit', 'security rule hits', 'qgw', ' SELECT rule_id, DATE_FORMAT(MIN(__time) ,''%Y-%m-%d %H:%i:%s'') AS first_hit, DATE_FORMAT(MAX(__time) ,''%Y-%m-%d %H:%i:%s'') AS last_hit FROM security_rule_hits WHERE rule_id IN ( ${rule_id} ) AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id', 'The time of the first and last hit for policy rules.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('security-rule-hits-current-throughput', 'security rule hits', 'qgw', 'SELECT SUM(in_bytes)* 8 / 15 AS in_bps, SUM(out_bytes)* 8 / 15 AS out_bps, SUM(in_bytes + out_bytes)* 8 / 15 AS total_bps FROM security_rule_hits WHERE __time >= FROM_UNIXTIME(UNIX_TIMESTAMP(now())-30) AND __time < FROM_UNIXTIME(UNIX_TIMESTAMP(now())-15) AND vsys_id IN ( ${vsys_id} ) AND rule_id IN ( ${rule_id} ) AND ( ${filter} )', 'To calculate the current security hit throughput, the metrics for each appliance are averaged over a 15-second interval. Additionally, the data ingestion latency is also set at 15 seconds.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('statistics-rule-hits-first-and-last-hit', 'statistics rule hits', 'qgw', 'SELECT rule_id, DATE_FORMAT( min( __time ), ''%Y-%m-%d %H:%i:%s'' ) AS first_hit, DATE_FORMAT( max( __time ), ''%Y-%m-%d %H:%i:%s'' ) AS last_hit FROM statistics_rule_hits WHERE rule_id IN ( ${rule_id} ) AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id', 'The time of the first and last hit for statistics policy rules.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('statistics-rule-hits-summary', 'statistics rule hits', 'qgw', 'SELECT rule_id, sum( hit_count ) AS hits, sum( in_bytes + out_bytes ) AS bytes FROM statistics_rule_hits WHERE __time >= ''${start}'' AND __time <''${end}'' AND rule_id IN ( ${rule_id} ) AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id', 'The hit count of specific rules.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('statistics-rule-hits-trend', 'statistics rule hits', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( sum_in_bytes )* 8 / 1 AS avg_in_bits_per_sec, AVG( sum_out_bytes )* 8 / 1 AS avg_out_bits_per_sec, AVG( sum_bytes )* 8 / 1 AS avg_bits_per_sec, SUM( sum_in_bytes ) AS total_in_bytes, SUM( sum_out_bytes ) AS total_out_bytes, SUM( sum_bytes ) AS total_bytes, AVG( sum_hit_count )/ 1 AS avg_hit_count_per_sec, SUM( sum_hit_count ) AS total_hit_count FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') AS stat_time, sum( in_bytes ) AS sum_in_bytes, sum( out_bytes ) AS sum_out_bytes, sum( in_bytes + out_bytes ) AS sum_bytes, sum( hit_count ) AS sum_hit_count FROM statistics_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND rule_id IN (${rule_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('proxy-rule-hits-summary', 'proxy rule hits', 'qgw', 'SELECT rule_id, SUM( hit_count ) AS hits, SUM( in_bytes + out_bytes ) AS bytes FROM proxy_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND rule_id IN ( ${rule_id} ) AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id', 'The hit count of specific rules.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('proxy-rule-hits-trend', 'proxy rule hits', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) AS stat_time, SUM( hit_count ) AS hits FROM proxy_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND rule_id IN ( ${rule_id} ) AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('proxy-rule-hits-first-and-last-hit', 'proxy rule hits', 'qgw', 'SELECT rule_id, DATE_FORMAT( MIN( __time ), ''%Y-%m-%d %H:%i:%s'' ) AS first_hit, DATE_FORMAT( MAX( __time ), ''%Y-%m-%d %H:%i:%s'' ) AS last_hit FROM proxy_rule_hits WHERE rule_id IN ( ${rule_id} ) AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id', 'The time of the first and last hit for policy rules.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('proxy-rule-hits-current-throughput', 'proxy rule hits', 'qgw', ' SELECT SUM( in_bytes )* 8 / 15 AS in_bps, SUM( out_bytes )* 8 / 15 AS out_bps, SUM( in_bytes + out_bytes )* 8 / 15 AS total_bps FROM proxy_rule_hits WHERE __time >= FROM_UNIXTIME( UNIX_TIMESTAMP( now())- 30 ) AND __time < FROM_UNIXTIME( UNIX_TIMESTAMP( now())- 15 ) AND vsys_id IN ( ${vsys_id} ) AND rule_id IN ( ${rule_id} ) AND ( ${filter} )', 'To calculate the current policy hit throughput, the metrics for each appliance are averaged over a 15-second interval. Additionally, the data ingestion latency is also set at 15 seconds.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('shaping-rule-hits-profiles', 'shaping rule hits', 'qgw', 'SELECT profile_id, SUM( in_bytes + out_bytes ) AS bytes, SUM( in_pkts + out_pkts ) AS packets, SUM( in_drop_pkts + out_drop_pkts ) AS drops, MAX( in_max_latency_us + out_max_latency_us ) AS max_latency_us, AVG( in_queue_len + out_queue_len ) AS avg_q, MAX( in_queue_len + out_queue_len ) AS max_q FROM traffic_shaping_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND profile_id IN ( ${profile_id} ) AND ( ${filter} ) GROUP BY profile_id', 'The hit count of specific shaping profiles.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('shaping-rule-hits-first-and-last-hit', 'shaping rule hits', 'qgw', 'SELECT rule_id, DATE_FORMAT( MAX( __time ), ''%Y-%m-%d %H:%i:%s'' ) AS last_hit, DATE_FORMAT( MIN( __time ), ''%Y-%m-%d %H:%i:%s'' ) AS first_hit FROM traffic_shaping_rule_hits WHERE vsys_id IN ( ${vsys_id} ) AND rule_id IN ( ${rule_id} ) AND ( ${filter} ) GROUP BY rule_id', 'The time of the first and last hit for policy rules.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('shaping-rule-hits-transferred-bytes', 'shaping rule hits', 'qgw', 'SELECT rule_id, SUM( in_bytes + out_bytes ) AS total_bytes FROM traffic_shaping_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND rule_id IN ( ${rule_id} ) AND ( ${filter} ) GROUP BY rule_id', 'The number of transferred bytes of specific shaping rules.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('shaping-rule-hits-profile-first-and-last-hit', 'shaping rule hits', 'qgw', 'SELECT profile_id, DATE_FORMAT( max( __time ), ''%Y-%m-%d %H:%i:%s'' ) AS last_hit, DATE_FORMAT( min( __time ), ''%Y-%m-%d %H:%i:%s'' ) AS first_hit, SUM( in_drop_pkts + out_drop_pkts ) AS drops FROM traffic_shaping_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND profile_id IN ( ${profile_id} ) AND ( ${filter} ) GROUP BY profile_id', 'The time of the first and last hit for shaping profiles.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('shaping-rule-hits-profile-hit-current-throughput', 'shaping rule hits', 'qgw', 'SELECT SUM( in_bytes )* 8 / 15 AS in_bps, SUM( out_bytes )* 8 / 15 AS out_bps, SUM( in_pkts )* 8 / 15 AS in_pps, SUM( out_pkts )* 8 / 15 AS out_pps, MAX( in_max_latency_us + out_max_latency_us ) AS max_latency_us, AVG( in_queue_len + out_queue_len ) AS avg_q, MAX( in_queue_len + out_queue_len ) AS max_q FROM traffic_shaping_rule_hits WHERE __time >= FROM_UNIXTIME( UNIX_TIMESTAMP( now())- 30 ) AND __time < FROM_UNIXTIME( UNIX_TIMESTAMP( now())- 15 ) AND vsys_id IN ( ${vsys_id} ) AND profile_id IN ( ${profile_id} ) AND ( ${filter} )', 'To calculate the current shaping profile hit throughput, the metrics for each appliance are averaged over a 15-second interval. Additionally, the data ingestion latency is also set at 15 seconds.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('shaping-rule-hits-throughput-trend', 'shaping rule hits', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) AS stat_time, SUM( in_bytes ) AS in_bytes, SUM( out_bytes ) AS out_bytes FROM traffic_shaping_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND rule_id IN ( ${rule_id} ) AND ( ${filter} ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) ORDER BY stat_time ASC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('shaping-rule-hits-profile-throughput-trend', 'shaping rule hits', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) AS stat_time, SUM( in_bytes ) AS in_bytes, SUM( out_bytes ) AS out_bytes FROM traffic_shaping_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND profile_id IN ( ${profile_id} ) AND ( ${filter} ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) ORDER BY stat_time ASC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('service-chaining-rule-hits-throughput-trend', 'service chaining rule hits', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) AS stat_time, SUM( sent_bytes ) AS sent_bytes, SUM( recv_bytes ) AS received_bytes FROM service_chaining_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND rule_id IN ( ${rule_id} ) AND ( ${filter} ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) ORDER BY stat_time ASC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('service-chaining-rule-hits-function-forwarder-profile-throughput-trend', 'service chaining rule hits', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) AS stat_time, SUM( sent_bytes ) AS sent_bytes, SUM( recv_bytes ) AS received_bytes FROM service_chaining_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND sff_profile_id IN ( ${sff_profile_id} ) AND ( ${filter} ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) ORDER BY stat_time ASC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
